#define VK_CHECK(expr, msg)                                  \
  do {                                                       \
    VkResult _r = (expr);                                    \
    if (_r != VK_SUCCESS) {                                  \
      if (err) *err = std::string(msg) + " (VkResult " +     \
                      std::to_string(static_cast<int>(_r)) + ")"; \
      return false;                                          \
    }                                                        \
  } while (0)

std::string LowerCopy(const std::string& s) {
  std::string out = s;
  for (char& c : out) {
    c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
  }
  return out;
}

bool IsUnsignedIntString(const std::string& s) {
  if (s.empty()) return false;
  for (char c : s) {
    if (!std::isdigit(static_cast<unsigned char>(c))) return false;
  }
  return true;
}

const char* DeviceTypeName(VkPhysicalDeviceType type) {
  switch (type) {
    case VK_PHYSICAL_DEVICE_TYPE_OTHER: return "other";
    case VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU: return "integrated";
    case VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU: return "discrete";
    case VK_PHYSICAL_DEVICE_TYPE_VIRTUAL_GPU: return "virtual";
    case VK_PHYSICAL_DEVICE_TYPE_CPU: return "cpu";
    default: return "unknown";
  }
}

bool MatchDeviceSelector(const RendererDevicePreference& preference,
                         uint32_t deviceIndex,
                         const VkPhysicalDeviceProperties& props,
                         const VkPhysicalDeviceDriverProperties& driver) {
  if (!preference.vulkanDevice || preference.vulkanDevice->empty()) {
    return true;
  }
  const std::string selector = LowerCopy(*preference.vulkanDevice);
  if (IsUnsignedIntString(selector)) {
    return deviceIndex == static_cast<uint32_t>(
                              std::strtoul(selector.c_str(), nullptr, 10));
  }

  std::string haystack = LowerCopy(props.deviceName);
  haystack += " ";
  haystack += LowerCopy(driver.driverName);
  haystack += " ";
  haystack += LowerCopy(driver.driverInfo);
  haystack += " ";
  haystack += DeviceTypeName(props.deviceType);
  char ids[64];
  std::snprintf(ids, sizeof(ids), " 0x%04x 0x%04x",
                unsigned(props.vendorID), unsigned(props.deviceID));
  haystack += ids;
  return haystack.find(selector) != std::string::npos;
}

int DeviceAutoScore(const VkPhysicalDeviceProperties& props,
                    bool hasRtFeatureSet) {
  int score = 0;
  switch (props.deviceType) {
    case VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU:
      score += 4000;
      break;
    case VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU:
      score += 3000;
      break;
    case VK_PHYSICAL_DEVICE_TYPE_VIRTUAL_GPU:
      score += 1000;
      break;
    case VK_PHYSICAL_DEVICE_TYPE_CPU:
      score -= 1000;
      break;
    default:
      break;
  }
  if (hasRtFeatureSet) score += 250;
  score += int(props.limits.maxImageDimension2D / 1024);
  return score;
}

bool PhysicalDeviceHasExtension(VkPhysicalDevice device, const char* name) {
  uint32_t n = 0;
  vkEnumerateDeviceExtensionProperties(device, nullptr, &n, nullptr);
  std::vector<VkExtensionProperties> exts(n);
  vkEnumerateDeviceExtensionProperties(device, nullptr, &n, exts.data());
  for (const VkExtensionProperties& ext : exts) {
    if (std::strcmp(ext.extensionName, name) == 0) return true;
  }
  return false;
}

bool PhysicalDeviceHasRtFeatureSet(VkPhysicalDevice device) {
#if defined(TUSDVIEW_HAVE_RT_SHADER) && TUSDVIEW_HAVE_RT_SHADER
  if (!PhysicalDeviceHasExtension(device, VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME) ||
      !PhysicalDeviceHasExtension(device, VK_KHR_RAY_QUERY_EXTENSION_NAME) ||
      !PhysicalDeviceHasExtension(device, VK_KHR_DEFERRED_HOST_OPERATIONS_EXTENSION_NAME)) {
    return false;
  }
  VkPhysicalDeviceRayQueryFeaturesKHR rqf{};
  rqf.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_QUERY_FEATURES_KHR;
  VkPhysicalDeviceAccelerationStructureFeaturesKHR asf{};
  asf.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_ACCELERATION_STRUCTURE_FEATURES_KHR;
  asf.pNext = &rqf;
  VkPhysicalDeviceVulkan12Features v12{};
  v12.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_2_FEATURES;
  v12.pNext = &asf;
  VkPhysicalDeviceFeatures2 f2{};
  f2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2;
  f2.pNext = &v12;
  vkGetPhysicalDeviceFeatures2(device, &f2);
  return rqf.rayQuery && asf.accelerationStructure &&
         v12.bufferDeviceAddress && v12.scalarBlockLayout &&
         f2.features.shaderInt64;
#else
  (void)device;
  return false;
#endif
}

light3d::Mat4 ToMat4(const float* m) {
  light3d::Mat4 r;
  std::memcpy(r.m, m, sizeof(r.m));
  return r;
}

void NormalMatrix3(const float m[16], float out9[9]) {
  const float a00 = m[0], a01 = m[4], a02 = m[8];
  const float a10 = m[1], a11 = m[5], a12 = m[9];
  const float a20 = m[2], a21 = m[6], a22 = m[10];
  const float det = a00 * (a11 * a22 - a12 * a21) -
                    a01 * (a10 * a22 - a12 * a20) +
                    a02 * (a10 * a21 - a11 * a20);
  if (std::fabs(det) < 1e-12f) {
    out9[0] = 1; out9[1] = 0; out9[2] = 0;
    out9[3] = 0; out9[4] = 1; out9[5] = 0;
    out9[6] = 0; out9[7] = 0; out9[8] = 1;
    return;
  }
  const float inv = 1.0f / det;
  out9[0] = (a11 * a22 - a12 * a21) * inv;
  out9[1] = -(a01 * a22 - a02 * a21) * inv;
  out9[2] = (a01 * a12 - a02 * a11) * inv;
  out9[3] = -(a10 * a22 - a12 * a20) * inv;
  out9[4] = (a00 * a22 - a02 * a20) * inv;
  out9[5] = -(a00 * a12 - a02 * a10) * inv;
  out9[6] = (a10 * a21 - a11 * a20) * inv;
  out9[7] = -(a00 * a21 - a01 * a20) * inv;
  out9[8] = (a00 * a11 - a01 * a10) * inv;
}

// Per-draw push constants for the mesh pipeline. Kept at 128 bytes -- the Vulkan
// *guaranteed minimum* maxPushConstantsSize (some drivers, e.g. amdvlk, expose
// exactly 128; pushing more is UB and crashes). Frame-constant data (viewProj,
// camPos, scene bbox, renderMode) lives in the set-5 Frame UBO instead; the
// vertex shader derives mvp = viewProj*model and the normal matrix from model.
struct PushC {
  float model[16];     // 64  world matrix (clip pos + world-space AOVs)
  float baseColor[4];  // 16  rgb + .w opacity
  float matAux[4];     // 16  .x metallic, .y roughness, .z alphaMode, .w alphaCutoff
  float emissive[4];   // 16  .xyz emissive (material AOV)
  int32_t ids[4];      // 16  .x matId, .y flags, .z meshId, .w pad
};
static_assert(sizeof(PushC) == 128, "PushC must match mesh shaders and fit maxPushConstantsSize>=128");

// Instanced flat-shaded prototype push constants (must match mesh_inst.vert/.frag).
// viewProj / camPos / scene bbox / renderMode are frame-constant -> set-5 Frame UBO.
struct InstPushC {
  int32_t draw[4];     // 16  .x = baseDraw: base slot into the DrawMeta SSBO
};
static_assert(sizeof(InstPushC) == 16, "InstPushC must match mesh_inst shaders");
// The per-draw metadata entry (set 6) is VulkanRenderer::DrawMetaCPU {int32_t
// ids[4]}, matching the shader's std430 DrawMeta{ivec4}: .x meshId, .y flag bits.

// Frame-constant uniforms shared by the mesh, tessellation and instanced
// pipelines (descriptor set 5). Persistently mapped, written once per frame.
struct FrameUBO {
  float disp[4];        // .x displacement scale, .y maxTessLevel (UI sliders)
  float viewProj[16];   // P * V (shader derives per-mesh mvp = viewProj*model)
  float camPos[4];      // .xyz camera world pos, .w depth-AOV normalizer
  float sceneMin[4];    // .xyz position-AOV scene bbox min
  float sceneExtent[4]; // .xyz position-AOV scene bbox size
  float lightDir[4];    // .xyz preview key light direction toward the light
  float lightColor[4];  // .rgb preview key light color/intensity
  int32_t mode[4];      // .x renderMode
  float envRot[16];     // world -> environment rotation (dome IBL; mat4)
  float iblColor[4];    // .rgb dome effectiveColor, .w = hasIbl (0/1)
  float iblParams[4];   // .x = prefiltered mip count
};

constexpr uint32_t kVkMatTexParamVec4s =
    static_cast<uint32_t>(kRasterMaterialTextureParamVec4s);
constexpr uint32_t kVkMatTexParamFloats =
    static_cast<uint32_t>(kRasterMaterialTextureParamFloats);
constexpr uint32_t kVkLightRtOpenPBRVec4s =
    static_cast<uint32_t>(kLightRtOpenPBRVec4s);
constexpr uint32_t kVkLightRtOpenPBRFloats =
    static_cast<uint32_t>(kLightRtOpenPBRFloats);
constexpr uint32_t kVkRtLightVec4s =
    static_cast<uint32_t>(kRtLightParamFloats / 4);
constexpr uint32_t kVkRtLightFloats =
    static_cast<uint32_t>(kRtLightParamFloats);

void InitVkMatTexParam(float* dst) {
  DrawMaterialCPU defaults;
  PackRasterMaterialTextureParams(defaults, dst);
}

// Ray-tracing compute push constants (must match raytrace.comp).
struct RtPushC {
  float invViewProj[16];
  float camPos[4];      // xyz + .w RenderMode
  float lightDir[4];    // xyz + .w depthScale
  float clearColor[4];
  float sceneMin[4];    // position AOV bbox
  float sceneExtent[4];
};

// Per-mesh descriptor for the RT shader (scalar layout, must match raytrace.comp).
struct MeshDescGPU {
  uint64_t vtxAddr;
  uint64_t idxAddr;
  uint64_t vtxColorAddr;     // per-vertex displayColor (vec3[]); 0 = none
  uint64_t uv1Addr;          // per-vertex 2nd texcoord (vec2[]); 0 = none
  uint64_t inflAddr;         // per-vertex blendshape influence (float[]); 0 = none
  uint64_t faceAddr;         // per-triangle source USD face id (uint[]); 0 = none
  uint64_t jointAddr;        // per-vertex 4 joint ids (uint[4]); 0 = unskinned
  uint64_t weightAddr;       // per-vertex 4 skin weights (float[4]); 0 = unskinned
  uint32_t matId;
  uint32_t geometricNormal;  // 1 = no authored normals -> geometric face normal
  float nrm0[4];             // normal matrix columns (xyz used)
  float nrm1[4];
  float nrm2[4];
};
static_assert(sizeof(MeshDescGPU) == 120, "MeshDescGPU must be tightly packed (scalar)");

// Per-TLAS-instance info, indexed by gl_InstanceID (the instance's position in the
// TLAS -- full 32-bit range, unlike the 24-bit instanceCustomIndex). Maps a hit
// back to its mesh + carries the per-instance tint/opacity.
struct InstanceInfoGPU {
  uint32_t meshId;       // index into the MeshDesc SSBO
  uint32_t useMaterial;  // 1 = non-instanced (material base + normalMat); 0 = tint + o2w
  uint32_t pad0, pad1;
  float tint[4];         // per-instance color/opacity or flatColor/flatOpacity
};
static_assert(sizeof(InstanceInfoGPU) == 32, "InstanceInfoGPU scalar layout");

// General column-major 4x4 inverse (for the camera's inverse view-projection).
bool Mat4Inverse(const float m[16], float out[16]) {
  float inv[16];
  inv[0] = m[5]*m[10]*m[15] - m[5]*m[11]*m[14] - m[9]*m[6]*m[15] +
           m[9]*m[7]*m[14] + m[13]*m[6]*m[11] - m[13]*m[7]*m[10];
  inv[4] = -m[4]*m[10]*m[15] + m[4]*m[11]*m[14] + m[8]*m[6]*m[15] -
           m[8]*m[7]*m[14] - m[12]*m[6]*m[11] + m[12]*m[7]*m[10];
  inv[8] = m[4]*m[9]*m[15] - m[4]*m[11]*m[13] - m[8]*m[5]*m[15] +
           m[8]*m[7]*m[13] + m[12]*m[5]*m[11] - m[12]*m[7]*m[9];
  inv[12] = -m[4]*m[9]*m[14] + m[4]*m[10]*m[13] + m[8]*m[5]*m[14] -
            m[8]*m[6]*m[13] - m[12]*m[5]*m[10] + m[12]*m[6]*m[9];
  inv[1] = -m[1]*m[10]*m[15] + m[1]*m[11]*m[14] + m[9]*m[2]*m[15] -
           m[9]*m[3]*m[14] - m[13]*m[2]*m[11] + m[13]*m[3]*m[10];
  inv[5] = m[0]*m[10]*m[15] - m[0]*m[11]*m[14] - m[8]*m[2]*m[15] +
           m[8]*m[3]*m[14] + m[12]*m[2]*m[11] - m[12]*m[3]*m[10];
  inv[9] = -m[0]*m[9]*m[15] + m[0]*m[11]*m[13] + m[8]*m[1]*m[15] -
           m[8]*m[3]*m[13] - m[12]*m[1]*m[11] + m[12]*m[3]*m[9];
  inv[13] = m[0]*m[9]*m[14] - m[0]*m[10]*m[13] - m[8]*m[1]*m[14] +
            m[8]*m[2]*m[13] + m[12]*m[1]*m[10] - m[12]*m[2]*m[9];
  inv[2] = m[1]*m[6]*m[15] - m[1]*m[7]*m[14] - m[5]*m[2]*m[15] +
           m[5]*m[3]*m[14] + m[13]*m[2]*m[7] - m[13]*m[3]*m[6];
  inv[6] = -m[0]*m[6]*m[15] + m[0]*m[7]*m[14] + m[4]*m[2]*m[15] -
           m[4]*m[3]*m[14] - m[12]*m[2]*m[7] + m[12]*m[3]*m[6];
  inv[10] = m[0]*m[5]*m[15] - m[0]*m[7]*m[13] - m[4]*m[1]*m[15] +
            m[4]*m[3]*m[13] + m[12]*m[1]*m[7] - m[12]*m[3]*m[5];
  inv[14] = -m[0]*m[5]*m[14] + m[0]*m[6]*m[13] + m[4]*m[1]*m[14] -
            m[4]*m[2]*m[13] - m[12]*m[1]*m[6] + m[12]*m[2]*m[5];
  inv[3] = -m[1]*m[6]*m[11] + m[1]*m[7]*m[10] + m[5]*m[2]*m[11] -
           m[5]*m[3]*m[10] - m[9]*m[2]*m[7] + m[9]*m[3]*m[6];
  inv[7] = m[0]*m[6]*m[11] - m[0]*m[7]*m[10] - m[4]*m[2]*m[11] +
           m[4]*m[3]*m[10] + m[8]*m[2]*m[7] - m[8]*m[3]*m[6];
  inv[11] = -m[0]*m[5]*m[11] + m[0]*m[7]*m[9] + m[4]*m[1]*m[11] -
            m[4]*m[3]*m[9] - m[8]*m[1]*m[7] + m[8]*m[3]*m[5];
  inv[15] = m[0]*m[5]*m[10] - m[0]*m[6]*m[9] - m[4]*m[1]*m[10] +
            m[4]*m[2]*m[9] + m[8]*m[1]*m[6] - m[8]*m[2]*m[5];
  float det = m[0]*inv[0] + m[1]*inv[4] + m[2]*inv[8] + m[3]*inv[12];
  if (std::fabs(det) < 1e-20f) return false;
  det = 1.0f / det;
  for (int i = 0; i < 16; ++i) out[i] = inv[i] * det;
  return true;
}

